		}
	}

	// Print errors
	if len(result.Errors) > 0 {
		fmt.Println()
		fmt.Println(ui.RenderCategory("Errors"))
		for _, err := range result.Errors {
			fmt.Printf("  %s  %s\n", ui.RenderFailIcon(), err)
		}
	}

	// Print fix suggestion
	if check.Fix != "" {
		fmt.Println()
		fmt.Printf("%s  %s\n", ui.RenderMuted("Fix:"), check.Fix)
	}

