	if result.Ready {
		fmt.Printf("%s\n", ui.RenderPass("✓ Migration validation passed"))
		return nil
	}
	fmt.Printf("%s\n", ui.RenderFail("✗ Migration validation failed"))
	return SilentExit()
}
